# Q23 round-2 report entries (idempotent): replaces Q23c, adds Q23d-g. python3 -I build_report_q23b.py
import json
p='/output/report.json'; r=json.load(open(p))
R=[x for x in r['results'] if not x['quantity'].startswith(('Q23c','Q23d','Q23e','Q23f','Q23g','Q23h'))]
A=[{"name":"data","value":"CO(2-1): 2015.1.00714.S 12m 0.18x0.17\" (spw1, <2844 km/s), 12m 0.82x0.68\" 2015.1.00902.S, 7m mosaic spw1 and SD spw17 (2015.1.00714.S); cores at Q5 HCN/HCO+ centres N (-0.06,+2.65\"), S (-0.15,-2.59\"); dense-gas v0/FWHM from out/q5/q5e_width.csv (HCN S 2711/117, N 2797/166 km/s)"},
 {"name":"convention","value":"RJ T_b = 1.222e3 S/(nu^2 a b); Planck equivalent in the Tk bounds; elliptical beams handled with radio_beam deconvolve/as_kernel; positions bilinear-interpolated; 1\"=213 pc"}]
def add(q,t,v,u,unit,conf,ev):
    R.append({"quantity":q,"target":t,"value":v,"uncertainty":u,"unit":unit,"confidence":conf,"evidence":ev,"assumptions":A})
add("Q23d: velocity-matched CO(2-1) T_b at the HCN/HCO+ line velocities (RJ), 12m 0.18\" cube convolved to circular beams","S and N cores; 0.26/0.57/1.0/1.7\"",
 "S (HCN v0 2711, FWHM 117 km/s; CO coverage 100%): mean T_b over the HCN FWHM 20.1/12.7/7.8/4.8 K vs peak-channel 31.2/19.2/11.8/7.0 K at 0.26/0.57/1.0/1.7\" (ratio 0.64-0.69); at v0 itself ~ peak because CO peaks at 2712 km/s, i.e. S CO-bright and dense gas share the velocity. HCO+ gives the same (20.0 K). N (HCN v0 2797, FWHM 166 km/s; the 0.18\" cube ends at 2844 km/s so only 75% of the FWHM is covered): mean 11.6/8.1/7.1/5.7 K vs peak 13.3/8.5/7.5/6.0 K; with the 0.82\" cube + 7m+SD at 1.0/1.7\": full-FWHM mean 7.9/6.5 K. N CO peak channel 2763-2790 km/s lies 7-35 km/s from the HCN centroid; the hottest CO within 0.3\" of N (21.2 RJ, 26.3 Planck) is at (+0.23,+0.17\") offset and v=2727 km/s, a different velocity and position from the HCN core.",
 "S: noise +-0.3 K (0.26\"); line-shape/centroid uncertainty of v0 ~ +-20 km/s changes mean by <1 K; N red wing uncovered (<=15% effect)","K","medium","scripts/q23b_vmatch_pos.py -> out/q23b/vmatch_pos.json; scripts/q23b_corrected.py -> out/q23b/corrected.json")
add("Q23e: position error budget for CO(2-1) core T_b (peak channel, RJ)","S and N cores at 0.26 and 0.57\"",
 "Offset grid (8 azimuths; min-max): S 0.26\": 31.2 (0\") / 29.7-32.3 (0.03) / 27.9-32.9 (0.06) / 25.0-33.0 (0.10) / 20.9-32.2 (0.15\"); N 0.26\": 13.3 / 12.8-13.8 / 12.7-14.5 / 12.7-16.1 / 12.0-17.7. 0.57\": S 19.2 / 18.5-19.8 / 17.7-20.3 / 16.5-20.8 / 14.9-21.1; N 8.5 / 8.5-8.9 / 8.5-9.6 / 8.5-10.5 / 8.5-11.5. Monte Carlo of the centre with sigma_pos=0.05\" (1500 draws, median [16,84]): S 0.26\" 30.3 [27.6,32.2], N 13.8 [13.2,14.2]; sigma_pos=0.10\": S 28.1 [21.5,31.9], N 13.8 [12.6,15.4]; 0.57\" sigma 0.05: S 19.1 [17.7,20.0], N 8.9 [8.5,9.7]. CO peak within 0.3\" of the core (0.26\" beam): S 33.4 RJ (38.7 Planck) at (+0.08,+0.05\"), N 21.2 RJ (26.3 Planck) at (+0.23,+0.17\"). N T_b is skewed high (CO brightens off-centre), S skewed low. The earlier ~+20-50% N excursion is the upper (north-east) azimuth at 0.10-0.15\" and reflects a real brighter CO peak 0.3\" from the HCN centre, not noise.",
 "position-dominated: S +-2.3 K (0.05\"), N +0.5/-0.6 K (0.05\") and up to +2.5 K at 0.10\"; noise-only 0.3-0.7 K understated this","K","medium","scripts/q23b_vmatch_pos.py (offset_grid, mc, max_r0.3) -> out/q23b/vmatch_pos.json")
add("Q23f: missing-flux budget of the 12m-only CO(2-1) cubes (7m mosaic + SD, elliptical beams)","S and N cores",
 "0.18\" cube convolved (elliptical radio_beam kernel) to the 0.82x0.68\" beam recovers 0.86 (N, peak) / 0.91 (S, line mean +-100 km/s) of the 0.82\" 12m cube (so the 0.18\" cube is 9-14% low at 0.8\"; the old circular 10-12% stands). 0.82\" 12m convolved to the 7m beam recovers 0.85-0.89 (N) / 0.83-0.85 (S) of the 7m mosaic; 7m convolved to the SD beam recovers 0.71-0.72 of SD. Additive image-plane feather correction dT = (7m-12m@7m beam)+(SD-7m@SD beam) = +0.4-0.6 K at the line at all beams: mean over HCN FWHM S +0.42 K, N +0.45 K, i.e. +2% (S 0.26\") to +9% (S 1.7\" HCN-mean) ; peak-channel 1.0\": S 11.8->12.9, N 7.5->8.8; 1.7\": S 7.0->7.7, N 6.0->7.5. Applying the correction to the 0.18\" cube alone is incomplete at 0.5-1\" (the 12m-0.82 vs 0.18-convolved deficit of 9-14% adds), so T_b at >=0.57\" are lower limits by ~10-15% and at 0.26\" by <=5-10%.",
 "correction +-50% of itself; assumes feather correction additive and spatially uniform over the beam","K","medium","scripts/q23b_missing_flux.py -> out/q23b/missing_flux.json; q23b_corrected.py -> out/q23b/corrected.json")
add("Q23g (replaces Q23c): conditional Tk lower limits from CO(2-1) and the beam-dilution fit","S and N cores",
 "Assuming CO(2-1) thick with Tex<=Tk and T_b = ff[J(Tex)-J(2.73)](1-e^-tau): at 0.26\" with ff=1, tau>=3: S Tk>=38 K (peak channel, 31.2 RJ) or >=26 K (mean over the HCN FWHM, 20.1 RJ); N >=19 K (peak) or >=17 K (HCN-mean). For ff=0.5: S 71/48 K, N 34/30; ff=0.3: S 115/76, N 52/46; ff=0.2: S 170/111, N 76/66 (tau=3; tau=1 values +40-50%). Beam dilution: a Gaussian source of FWHM theta fitted to T_b(beam) over 0.18-1.7\": S theta=0.71+-0.08\" (150 pc), Ts=33.9+-2.3 K peak (21.7+-1.4 HCN-mean) giving ff=0.88/0.61/0.15 at 0.26/0.57/1.7\"; N theta=1.1-1.3+-0.3\", Ts=13.4+-1.7 (11.6+-1.1), ff=0.95/0.79/0.3. So at 0.26\" the CO core is ~unresolved-to-filled (ff 0.9) for the tau>=3 case and the HCN-velocity-matched S lower limit Tk>=26 K is only marginally above the 17-25 K S RADEX core; the peak-channel limit Tk>=38 K is in tension with 17-25 K only if the HCN gas fills the CO-bright 0.26\" core at that velocity. Conditional statement: S cannot be a 17-25 K space-filling core if CO is thick, co-spatial and 12m flux is complete (a 5-10% missing flux raises the limits); it can be if CO(2-1) is sub-thermal/partly thin (tau(CO)~1 lowers Tex, not raising Tk_min above the table at tau>=3 but the tau=1 row gives the larger limits), or if HCN/HCO+ is cooler layer/clump along the line of sight. 13CO/C18O(2-1) is not available at this resolution, so tau(CO) is not constrained; velocity mismatch, co-spatiality and CO-vs-HCN beam dilution are unmodelled. Use as Q22 prior: Tk(S) lower bound 26-38 K at 0.26\" for ff~1, tau>=3 (>=70 K for ff~0.5); N >=17-19 K.",
 "fit uncertainties theta +-0.08\" (S), +-0.3\" (N); Tk_min +-15% from T_b systematics (position, flux)","K","medium","scripts/q23c_tk_ff.py -> out/q23b/tk_ff.json")
add("Q23h: S nucleus CO peak vs Brunetti+2021 abstract maximum (37 K)","S core, 55 pc beam",
 "At 0.26\" (55 pc): S core 31.2 RJ (35.6 Planck) at the HCN centre, 33.4 RJ (38.7 Planck) at the CO maximum within 0.3\"; native 0.18\": 34.8 RJ (40.0 Planck), max within half beam 38.2 RJ. The abstract's 'as large as 37 K' is therefore reproduced for either RJ (33.4) or Planck (38.7) within ~10%; the paper text we read does not state the convention, so the check is convention-limited. Table-2 HTML vs PDF: arXiv text layer and ar5iv are the same source, so equality (12 rows x 15 values) is a null test; the typeset MNRAS PDF was not read separately.",
 "convention ambiguity 10-15%","K","medium","scripts/q23b_vmatch_pos.py (max_r0.3); out/q23_table2_html.txt; literature 2021MNRAS.500.4730B")
